// The shape p-limit v5 has: a private #async_hooks import that is the builtin
// on node and a stub elsewhere, and AsyncResource.bind to keep the caller's
// context on queued work.
const { AsyncResource } = require('#async_hooks');
const { AsyncLocalStorage } = require('async_hooks');
const als = new AsyncLocalStorage();
const queued = als.run('limited', () => AsyncResource.bind((fn) => fn()));
exports.run = (fn) => new Promise((resolve) => setTimeout(() => resolve(queued(fn)), 1));
exports.als = als;
